#!/usr/bin/env bash
set -euo pipefail
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"
source "$ROOT_DIR/scripts/lib/immutable-tags.sh"
source "$ROOT_DIR/scripts/lib/portable-search.sh"
mode="${1:-feature}"
case "$mode" in feature|--feature) mode="feature";; merged-main|--merged-main) mode="merged-main";; *) echo "usage: $0 [feature|merged-main]" >&2; exit 2;; esac
git_ref_exists(){ git rev-parse --verify --quiet "$1" >/dev/null 2>&1; }
comparison_base(){ local c mb; if [[ -n "${GITHUB_BASE_REF:-}" ]]; then for c in "origin/${GITHUB_BASE_REF}" "${GITHUB_BASE_REF}"; do if git_ref_exists "$c"; then mb="$(git merge-base HEAD "$c" 2>/dev/null || true)"; [[ -n "$mb" ]] && { echo "$mb"; return 0; }; fi; done; fi; for c in origin/main main; do if git_ref_exists "$c"; then mb="$(git merge-base HEAD "$c" 2>/dev/null || true)"; [[ -n "$mb" ]] && { echo "$mb"; return 0; }; fi; done; git_ref_exists HEAD~1 && { echo HEAD~1; return 0; }; return 1; }
is_aion224_source_path(){ case "$1" in services/brain-api/src/aion_brain/contracts/governed_learning_memory_persistence.py|services/brain-api/src/aion_brain/governed_learning_memory/local_persistence_policy.py|services/brain-api/src/aion_brain/governed_learning_memory/local_sqlite_schema.py|services/brain-api/src/aion_brain/governed_learning_memory/local_sqlite_store.py|services/brain-api/src/aion_brain/governed_learning_memory/persistence_approval.py|services/brain-api/src/aion_brain/governed_learning_memory/knowledge_content.py|services/brain-api/src/aion_brain/governed_learning_memory/knowledge_persistence.py|services/brain-api/src/aion_brain/governed_learning_memory/memory_projection_persistence.py|services/brain-api/src/aion_brain/governed_learning_memory/persistence_transactions.py|services/brain-api/src/aion_brain/governed_learning_memory/persistence_integrity.py|services/brain-api/src/aion_brain/governed_learning_memory/backup_restore.py|services/brain-api/src/aion_brain/governed_learning_memory/persistence_evidence.py|services/brain-api/src/aion_brain/governed_learning_memory/__init__.py) return 0;; esac; return 1; }
is_aion226_path(){ case "$1" in docs/adr/0190-operator-approved-non-factual-engagement-learning-shadow-application.md|scripts/governed-learning-memory-engagement-*.sh|scripts/governed-learning-memory-engagement-*.py|scripts/lib/governed_learning_memory_engagement_*.py|services/brain-api/src/aion_brain/contracts/governed_engagement_learning.py|services/brain-api/src/aion_brain/governed_learning_memory/engagement_*.py|services/brain-api/tests/governed_engagement_learning_test_helpers.py|services/brain-api/tests/test_governed_engagement_learning_*.py) return 0;; esac; return 1; }
is_allowed_path(){ is_aion226_path "$1" && return 0; case "$1" in README.md|AGENTS.md|docs/governed-learning-memory/*|docs/release/governed-learning-memory-*|docs/release/v02-release-readiness-delta.md|docs/adr/0187-promotion-transaction-evaluation-and-local-append-only-knowledge-persistence-authorization.md|docs/adr/0188-operator-approved-local-append-only-knowledge-and-memory-projection-persistence.md|docs/adr/0191-engagement-shadow-application-evaluation-and-controlled-local-continual-learning-pilot-authorization.md|docs/adr/README.md|docs/project-status.md|docs/architecture.md|docs/brain-contract.md|docs/policy-model.md|docs/visual-brain.md|examples/governed-learning-memory/*|operator-console-static/index.html|operator-console-static/app.js|operator-console-static/README.md|operator-console-static/demo-data/governed-learning-memory-*.json|scripts/auth-design-check.sh|scripts/connector-runtime-no-external-call-regression.sh|scripts/knowledge-intelligence-claim-graph-operator-evaluation-no-go-regression.sh|scripts/knowledge-intelligence-domain-expert-mesh-authorization-no-go-regression.sh|scripts/knowledge-intelligence-domain-expert-mesh-operator-evaluation-no-go-regression.sh|scripts/knowledge-intelligence-epistemic-assessment-operator-evaluation-no-go-regression.sh|scripts/knowledge-intelligence-integrated-research-agent-operator-evaluation-no-go-regression.sh|scripts/knowledge-intelligence-program-final-evaluation-no-go-regression.sh|scripts/knowledge-intelligence-research-operator-evaluation-no-go-regression.sh|scripts/knowledge-intelligence-tool-verification-authorization-no-go-regression.sh|scripts/knowledge-intelligence-verified-knowledge-authorization-no-go-regression.sh|scripts/knowledge-intelligence-verified-memory-operator-evaluation-no-go-regression.sh|scripts/operator-console-static-check.sh|scripts/static-console-safety-check.sh|scripts/governed-learning-memory-promotion-operator-evaluation-check.sh|scripts/governed-learning-memory-promotion-operator-evaluation-no-go-regression.sh|scripts/governed-learning-memory-local-persistence-authorization-check.sh|scripts/governed-learning-memory-local-persistence-authorization-no-go-regression.sh|scripts/governed-learning-memory-local-persistence-runtime-hold.sh|scripts/governed-learning-memory-local-persistence-check.sh|scripts/governed-learning-memory-local-persistence-no-go-regression.sh|scripts/governed-learning-memory-local-persistence-pilot-evidence-check.sh|scripts/governed-learning-memory-local-persistence-run.py|scripts/governed-learning-memory-engagement-application-operator-evaluation-check.sh|scripts/governed-learning-memory-engagement-application-operator-evaluation-no-go-regression.sh|scripts/governed-learning-memory-continual-learning-pilot-authorization-check.sh|scripts/governed-learning-memory-continual-learning-pilot-authorization-no-go-regression.sh|scripts/governed-learning-memory-continual-learning-pilot-runtime-hold.sh|scripts/governed-learning-memory-program-authorization-check.sh|scripts/governed-learning-memory-program-no-go-regression.sh|scripts/governed-learning-memory-runtime-hold.sh|scripts/governed-learning-memory-promotion-transaction-check.sh|scripts/governed-learning-memory-promotion-transaction-no-go-regression.sh|scripts/lib/governed_learning_memory_promotion_operator_evaluation.py|scripts/lib/governed_learning_memory_local_persistence_authorization.py|scripts/lib/governed_learning_memory_engagement_application_operator_evaluation.py|scripts/lib/governed_learning_memory_continual_learning_pilot_authorization.py|scripts/lib/cognitive_architecture_governance.py|scripts/lib/v02-production-auth-scan-exclusions.sh|scripts/production-auth-core-no-go-regression.sh|services/brain-api/tests/conftest.py|services/brain-api/tests/test_governed_learning_memory_*.py) return 0;; esac; is_aion224_source_path "$1" && return 0; return 1; }
is_prohibited_path(){ is_aion226_path "$1" && return 1; case "$1" in .github/workflows/*|services/brain-api/src/aion_brain/*|services/brain-api/pyproject.toml|packages/aion-sdk-python/src/*|migrations/*|services/brain-api/migrations/*|infra/postgres/migrations/*|package.json|package-lock.json|pnpm-lock.yaml|yarn.lock|bun.lockb|poetry.lock|uv.lock|Pipfile|Pipfile.lock|*/package.json|*/package-lock.json|*/pnpm-lock.yaml|*/yarn.lock|*/bun.lockb) is_aion224_source_path "$1" && return 1; return 0;; esac; return 1; }
changed_entries(){ local base; if [[ "$mode" == "feature" ]]; then if base="$(comparison_base)"; then git diff --name-status "$base" HEAD --; else echo "WARN: comparison base unavailable; relying on working tree and committed artifacts" >&2; fi; fi; git diff --name-status HEAD --; git diff --cached --name-status --; git status --porcelain=v1 --untracked-files=all | awk '/^\?\? / {print "A	" substr($0, 4)}'; }
while IFS=$'	' read -r status path extra; do [[ -n "${status:-}" ]] || continue; [[ "$status" == D* || "$status" == R* ]] && { echo "ERROR: deletion or rename is not authorized: $status $path ${extra:-}" >&2; exit 1; }; for changed in "$path" "${extra:-}"; do [[ -n "$changed" ]] || continue; is_prohibited_path "$changed" && { echo "ERROR: prohibited AION-223 surface changed: $changed" >&2; exit 1; }; is_allowed_path "$changed" || { echo "ERROR: path outside AION-223 local persistence authorization scope: $changed" >&2; exit 1; }; done; done < <(changed_entries)
"$ROOT_DIR/services/brain-api/.venv/bin/python" - <<'PY'
import json
from pathlib import Path
root = Path.cwd()
state = json.loads((root / "docs/governed-learning-memory/program-ledger.json").read_text())["program_state"]
implemented_states = {
    "governed_learning_memory_local_append_only_persistence_implemented_operator_invoked_isolated_pending_closeout",
    "governed_learning_memory_engagement_application_authorized_not_implemented",
    "governed_learning_memory_engagement_application_implemented_shadow_only_pending_closeout",
    "governed_learning_memory_controlled_local_continual_learning_pilot_authorized_not_implemented",
}
paths = [
    "services/brain-api/src/aion_brain/contracts/governed_learning_memory_persistence.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/local_persistence_policy.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/local_sqlite_schema.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/local_sqlite_store.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/persistence_approval.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/knowledge_content.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/knowledge_persistence.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/memory_projection_persistence.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/persistence_transactions.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/persistence_integrity.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/backup_restore.py",
    "services/brain-api/src/aion_brain/governed_learning_memory/persistence_evidence.py",
]
if state in implemented_states:
    missing = [path for path in paths if not (root / path).exists()]
    if missing:
        raise SystemExit(f"ERROR: AION-224 source missing after implementation: {missing[0]}")
else:
    present = [path for path in paths if (root / path).exists()]
    if present:
        raise SystemExit(f"ERROR: AION-224 source exists before implementation: {present[0]}")
PY
if git ls-files '*.db' '*.sqlite' '*.sqlite3' '*.jsonl' '*.state' '*.sql' | rg -n '(^|/)governed-learning-memory|(^|/)governed_learning_memory|knowledge.*state|memory.*state|local-persistence'; then echo "ERROR: tracked local persistence state or schema candidate exists" >&2; exit 1; fi
python_scan_paths=(scripts/lib/governed_learning_memory_promotion_operator_evaluation.py scripts/lib/governed_learning_memory_local_persistence_authorization.py)
if rg -n '^[[:space:]]*(from|import)[[:space:]]+(sqlite3|subprocess|socket|requests|httpx|aiohttp|urllib[.]request|git|github|playwright|selenium)([[:space:].]|$)|(^|[^[:alnum:]_])(sqlite3|subprocess|socket|requests|httpx|aiohttp|git|github|playwright|selenium)[.]|urllib[.]request|(^|[^[:alnum:]_])os[.]system|ApprovalService|ApprovalRepository|MemoryRepository|BeliefRepository|create_belief[(]|persist_knowledge[(]' "${python_scan_paths[@]}"; then echo "ERROR: prohibited runtime or write primitive found" >&2; exit 1; fi
scan_paths=(docs/governed-learning-memory docs/release examples/governed-learning-memory operator-console-static/demo-data)
if rg -n 'automatic_knowledge_promotion_enabled["[:space:]]*:[[:space:]]*true|production_exposure["[:space:]]*:[[:space:]]*true|v02_release_ready["[:space:]]*:[[:space:]]*true|background_persistent_knowledge_write_enabled["[:space:]]*:[[:space:]]*true|production_persistent_knowledge_write_enabled["[:space:]]*:[[:space:]]*true' "${scan_paths[@]}"; then echo "ERROR: prohibited local persistence safety flag enabled" >&2; exit 1; fi
if git tag --list 'v0.2*' 'aion-v0.2*' | rg -n '.+'; then echo "ERROR: v0.2 tag exists" >&2; exit 1; fi
if command -v gh >/dev/null 2>&1; then if gh release view v0.2 >/dev/null 2>&1 || gh release view aion-v0.2 >/dev/null 2>&1; then echo "ERROR: v0.2 release exists" >&2; exit 1; fi; fi
aion_confirm_immutable_v01_tag_history >/dev/null
echo "governed learning memory local persistence authorization no-go PASS"
